// 仅新profile核真实劳动完成与原赈济付款截面；没有新来源就不能冒称占领后的暂停已解除。
#include "political_governance_continuation_detail.hpp"
#include "resident/domains/tasks/governance_task_state.hpp"
#include "resident/domains/local_economy/relief/public_relief_rules.hpp"
#include <limits>
namespace hanmo::resident {namespace {
using namespace governance_continue_detail;
// 只限两个已由所属域完整核载荷的实际执行头；未完成Action或任意fact不授历史权限。
Outcome<Integer> boundary(const CommonStore& c,const StableId& id,bool work){const auto* h=c.state().facts.find(id);auto n=organization_instance_sequence(id,work?"governance_work":"public_relief_distributed");if(!h||h->id!=id||h->kind!=(work?"governance_work_completed":"public_relief_distributed")||h->domain!=(work?"tasks":"local_economy")||!n||*n>=c.state().next_instance_id)return {false,0,common_failure("GovernanceContinuationExecutionBoundaryMismatch",id).error};return {true,*n,{}};}
// 空职型连续性在执行时核新署当时的真实持有人；后来补任不能倒填过去空职。
Status office_before(const PoliticalGovernanceContinuationContext& x,const PoliticalGovernanceContinuation& r,Integer tick,const StableId& id,Integer cutoff){
 const auto* initial=x.organization_catalog.offices.find(r.authority.office_id);const auto* current=x.organizations.offices.find(r.authority.office_id);if(!initial||!current||initial->organization_id!=r.authority.organization_id||current->organization_id!=r.authority.organization_id)return common_failure("GovernanceContinuationOfficeHistoryUnavailable",id);
 auto holder=initial->holder_actor_id;auto at=holder;Integer epoch=initial->epoch,last=0,last_tick=-1;StableId previous;
 for(const auto& row:x.organizations.facts.rows()){const auto& f=row.second;if(f.kind!="organization_office_changed"||f.office_id!=r.authority.office_id)continue;auto n=organization_instance_sequence(row.first,"organization");const auto* h=x.common.state().facts.find(row.first);if(row.first!=f.id||!n||*n<=last||*n>=x.common.state().next_instance_id||*n==cutoff||!h||h->id!=row.first||h->kind!=f.kind||h->domain!="organization"||f.organization_id!=r.authority.organization_id||f.tick<last_tick||f.tick>x.common.tick()||epoch==std::numeric_limits<Integer>::max()||(!previous.empty()&&!before(x.common,previous,f.id)))return common_failure("GovernanceContinuationOfficeHistoryUnavailable",id);const bool earlier=*n<cutoff;if(earlier!=before(x.common,f.id,id)||(earlier&&f.tick>tick)||(!earlier&&f.tick<tick))return common_failure("GovernanceContinuationOfficeHistoryUnavailable",id);++epoch;holder=f.actor_id.empty()?std::optional<StableId>{}:std::optional<StableId>{f.actor_id};if(earlier)at=holder;last=*n;last_tick=f.tick;previous=f.id;}
 if(epoch!=current->epoch||holder!=current->holder_actor_id||!at||!x.common.actor(*at))return common_failure("GovernanceSuccessorOfficeVacantBeforeExecution",id);
 const auto* person=x.common.actor(*at);if(!x.death_origin)return person->alive?common_success():common_failure("GovernanceContinuationLifeHistoryUnavailable",*at);auto death=x.death_origin(*at);if(!death.ok)return {false,{},death.error};if(!death.value)return person->alive?common_success():common_failure("GovernanceContinuationLifeHistoryUnavailable",*at);
 const auto& d=*death.value;auto n=organization_instance_sequence(d.casualty_fact_id,"military");const auto* h=x.common.state().facts.find(d.casualty_fact_id);if(d.actor_id!=*at||d.battle_id.empty()||d.tick<0||d.tick>x.common.tick()||!n||*n>=x.common.state().next_instance_id||!h||h->id!=d.casualty_fact_id||h->kind!="military_casualties"||h->domain!="military")return common_failure("GovernanceContinuationLifeHistoryUnavailable",*at);const bool earlier=*n<cutoff;if(earlier!=before(x.common,d.casualty_fact_id,id)||(earlier&&d.tick>tick)||(!earlier&&d.tick<tick))return common_failure("GovernanceContinuationLifeOrderMismatch",*at);return earlier?common_failure("GovernanceSuccessorOfficeDeadBeforeExecution",id):common_success();
}
// 有真实接管登记时必须匹配该截面最后裁定；更早或更晚的续办不能跨次占领复用。
Status execution(const PoliticalGovernanceContinuationContext& x,const GovernanceTaskAcceptance& task,const StableId& id,Integer tick,bool work){
 auto cutoff=boundary(x.common,id,work);if(!cutoff.ok)return {false,{},cutoff.error};if(tick<task.accepted_tick||tick>x.common.tick())return common_failure("GovernanceContinuationExecutionTickMismatch",id);auto e=x.takeover.political_responsibility_before_fact({PoliticalResponsibilityKind::relief_contract,task.contract_id,{},{}},id,tick,x.common.state().identity);if(!e.ok)return {false,{},e.error};if(!e.value)return common_success();
 auto a=x.original_authority.governance_authority_approval(task.authority_source_fact_id);if(!a.ok)return {false,{},a.error};auto valid=execution_source(x,a.value,task,*e.value);if(!valid.ok)return valid;const auto& d=*e.value->decision;const PoliticalGovernanceContinuation* selected=nullptr;Integer last=0;
 for(const auto& row:x.state.continuations.rows()){const auto& r=row.second;if(r.task_id!=task.task_id)continue;auto n=source_sequence(x.common,r.id);if(!n.ok)return {false,{},n.error};const bool earlier=n.value<cutoff.value;if(earlier!=before(x.common,r.id,id)||(earlier&&r.tick>tick)||(!earlier&&r.tick<tick))return common_failure("GovernanceContinuationExecutionOrderMismatch",id);if(earlier&&n.value>last){last=n.value;selected=&r;}}
 if(!selected||selected->authority_fact_id!=task.authority_source_fact_id||selected->contract_id!=task.contract_id||selected->executor_actor_id!=task.executor_actor_id||selected->registration_fact_id!=e.value->registration_fact_id||selected->approval_fact_id!=d.takeover_fact_id||selected->decision_fact_id!=d.decision_fact_id)return common_failure("GovernanceContinuationBeforeExecutionRequired",id);
 return a.value.continuity_policy_id=="stop_when_vacant"?office_before(x,*selected,tick,id,cutoff.value):a.value.continuity_policy_id=="continue_under_organization"?common_success():common_failure("UnsupportedGovernanceContinuity",a.value.continuity_policy_id);
}
}
Status validate_political_governance_continued_execution(const PoliticalGovernanceContinuationContext& x,const GovernanceTaskState& tasks,const PublicReliefState& relief){
 if(x.phase)return common_failure("GovernanceContinuationExecutionRequiresCommittedClock");auto valid=validate_political_governance_continuations(x);if(!valid.ok)return valid;
 for(const auto& row:tasks.governance_contracts.rows()){auto source=x.tasks.governance_task_source(row.first);if(!source.ok)return {false,{},source.error};if(source.value.acceptance.fact_id!=row.second.acceptance.fact_id)return common_failure("GovernanceContinuationWrongTaskRead",row.first);if(source.value.work){valid=execution(x,source.value.acceptance,source.value.work->fact_id,source.value.work->completed_tick,true);if(!valid.ok)return valid;}}
 for(const auto& row:relief.receipts.rows()){const auto& r=row.second;auto source=x.tasks.governance_task_source(r.task_id);if(!source.ok)return {false,{},source.error};if(row.first!=r.id||source.value.acceptance.contract_id!=r.contract_id||source.value.acceptance.authority_source_fact_id!=r.authority_source_fact_id||source.value.acceptance.fact_id!=r.acceptance_fact_id)return common_failure("GovernanceContinuationWrongReliefSource",row.first);valid=execution(x,source.value.acceptance,r.id,r.tick,false);if(!valid.ok)return valid;}
 return common_success();
}
}
